package com.wardengambits.app.audio

/** Short sound effects; the files live in res/raw and are generated by tools/sfx/generate_sfx.py. */
enum class Sfx { ACTION, DEFEAT_ENEMY, VICTORY, DEFEAT, KEY_SWORD, KEY_SHIELD, KEY_PUNCH }

/** Plays the game's sound effects and the looping combat ambience. */
interface SoundPlayer {
    fun playSfx(sfx: Sfx)
    fun startAmbient()
    fun pauseAmbient()
    fun stopAmbient()
    fun setEnabled(enabled: Boolean)
    fun release()
}
